mapper.select:
SELECT task_pickup_dispatch.* FROM pd_task_pickup_dispatch task_pickup_dispatch
LEFT JOIN pd_order pdorder ON task_pickup_dispatch.order_id=pdorder.id
LEFT JOIN pd_transport_order transport_order ON pdorder.id=transport_order.order_id
LEFT JOIN pd_auth_user auth_user ON task_pickup_dispatch.courier_id = auth_user.id


        AND task_pickup_dispatch.task_type = #{taskType}


        AND task_pickup_dispatch.status = #{status}


        AND transport_order.id LIKE CONCAT('%',#{transportOrderId},'%')


        AND auth_user.name LIKE CONCAT('%',#{courierName},'%')


        AND pdorder.sender_name LIKE CONCAT('%',#{senderName},'%')


        AND pdorder.sender_province_id = #{senderProvinceId}


        AND pdorder.sender_city_id = #{senderCityId}


        AND pdorder.receiver_name LIKE CONCAT('%',#{receiverName},'%')


        AND pdorder.receiver_province_id = #{receiverProvinceId}


        AND pdorder.receiver_city_id = #{receiverCityId}


order by task_pickup_dispatch.create_time desc

SELECT * FROM pd_transport_order transport_order
LEFT JOIN pd_order pdorder ON transport_order.order_id = pdorder.id


        AND transport_order.id LIKE CONCAT('%',#{id},'%')


        AND transport_order.status = #{status}


        AND pdorder.sender_name LIKE CONCAT('%',#{senderName},'%')


        AND pdorder.sender_phone LIKE CONCAT('%',#{senderPhone},'%')


        AND pdorder.sender_province_id = #{senderProvinceId}


        AND pdorder.sender_city_id = #{senderCityId}


        AND pdorder.sender_county_id = #{senderCountyId}


        AND pdorder.receiver_name LIKE CONCAT('%',#{receiverName},'%')


        AND pdorder.receiver_phone LIKE CONCAT('%',#{receiverPhone},'%')


        AND pdorder.receiver_province_id = #{receiverProvinceId}


        AND pdorder.receiver_city_id = #{receiverCityId}


        AND pdorder.receiver_county_id = #{receiverCountyId}


order by transport_order.create_time desc
